import { BundleScript, ScriptRouter, type ScriptCommand } from "../../../../../../../🔨️modules/🏃️process/🧭️routing/🟦️.ts";
import { runRepositoryCommand } from "../../../🏃️process/🎛️owned-execution/🟦️.ts";
import { artifactRustCargoArguments, validateNativeCargoArguments } from "../🎛️native-input/🟦️.ts";
import { buildRepositoryCargoArtifacts } from "../🏗️native-build/🟦️.ts";

/**
 * 🧪️ Runs an artifact crate through the repository's level filters, Nextest profile and assertion budget.
 *
 * 🎛️ `testFeatures` names the Cargo features whose `#[cfg(feature = …)]` trees hold tests that would
 * otherwise never compile, let alone run: a crate whose app assembly is feature-gated reports a
 * cheerful green over a fraction of its suite without them. They go in front of the caller's own
 * arguments and reach Nextest as build selectors (`--features` is a required build option in
 * `partitionNextestExecutionFilters`), so the warm build and the execution pass agree.
 */
export async function runArtifactRustTests(cargoName: string, repoRoot: string, segments: string[], testFeatures: readonly string[] = []): Promise<void> {
  const { runRepositoryCargoTests } = await import("../../../🟦️.ts");
  const { rest } = resolveTestLevel(segments);
  validateNativeCargoArguments("test", rest);
  const featureArgs = testFeatures.flatMap((feature) => ["--features", feature]);
  const stopProgress = startNativeProgress(`artifact-rust:${cargoName}:test`);
  try { await runRepositoryCargoTests([cargoName], repoRoot, [...featureArgs, ...rest]); }
  finally { stopProgress(); }
}

/**
 * 🔬️ One artifact's TypeScript twin: the second, independent implementation of a law whose fixture
 * the Rust suite also answers. Returns how many assertions it carried, so a twin that silently
 * stopped asserting is visible as a collapsing count rather than a passing run.
 */
export type ArtifactTwinSelfTest = { readonly name: string; readonly run: () => number };

/** 📦️ Runs an independently owned Rust artifact package through the shared Nx-native contract. */
export async function runArtifactRustPackageMain(packageRoot: string, cargoName: string, options: { readonly testFeatures?: readonly string[]; readonly twins?: readonly ArtifactTwinSelfTest[]; readonly commands?: Readonly<Record<string, ScriptCommand>>; readonly testCommands?: Readonly<Record<string, ScriptCommand>>; readonly snapshotSqliteTests?: readonly string[]; readonly snapshotSqliteTestFeatures?: readonly string[]; readonly snapshotSqliteTestBudgetMs?: number; readonly snapshotSqliteTestGroups?: readonly (readonly string[])[] } = {}): Promise<void> {
  if (options.snapshotSqliteTestBudgetMs !== undefined && (!Number.isSafeInteger(options.snapshotSqliteTestBudgetMs) || options.snapshotSqliteTestBudgetMs <= 0)) throw new Error("Owned SQLite snapshot test budget must be a positive safe integer");
  const snapshotSources = options.snapshotSqliteTests?.map(path => resolve(packageRoot, path)) ?? [];
  const snapshotGroups = options.snapshotSqliteTestGroups?.map(group => group.map(path => resolve(packageRoot, path))) ?? [snapshotSources];
  if (options.snapshotSqliteTestGroups !== undefined) {
    const selected = snapshotGroups.flat(), owned = new Set(snapshotSources);
    if (!snapshotGroups.length || snapshotGroups.some(group => !group.length) || owned.size !== snapshotSources.length || selected.length !== snapshotSources.length || new Set(selected).size !== selected.length || selected.some(path => !owned.has(path))) throw new Error("Owned SQLite snapshot source groups must include every owned source exactly once");
  }
  class BuildScript extends BundleScript {
    async run(segments: string[]): Promise<void> {
      const { cargoArgs } = artifactRustCargoArguments("build", segments);
      await buildRepositoryCargoArtifacts(relative(this.repoRoot, resolve(this.root, "Cargo.toml")), cargoArgs, this.repoRoot);
    }
  }
  class CheckScript extends BundleScript {
    async run(segments: string[]): Promise<void> {
      const { cargoArgs } = artifactRustCargoArguments("check", segments);
      await runRepositoryCommand("cargo", ["check", "--locked", "--manifest-path", resolve(this.root, "Cargo.toml"), ...cargoArgs], this.repoRoot, `artifact-rust:${cargoName}:check`);
    }
  }
  class TestScript extends BundleScript {
    async run(segments: string[]): Promise<void> {
      if (segments[0] && options.testCommands && Object.hasOwn(options.testCommands, segments[0])) {
        const router = new ScriptRouter(this.root, this.repoRoot);
        for (const [name, Command] of Object.entries(options.testCommands)) router.register(name, Command);
        await router.run(segments);
        return;
      }
      for (const twin of options.twins ?? []) console.log(`[TRACE] ${twin.name}-twin checks=${twin.run()}`);
      await runArtifactRustTests(cargoName, this.repoRoot, segments, options.testFeatures);
    }
  }
  class CanonicalArchitectureScript extends BundleScript {
    run(): void {
      for (const twin of options.twins ?? []) console.log(`artifact-contribution: ${twin.name} checks=${twin.run()}`);
    }
  }
  class SnapshotSqliteTestScript extends BundleScript {
    async run(segments: string[]): Promise<void> {
      const mode = segments[0];
      if (segments.length > 1 || (mode !== undefined && mode !== "source" && mode !== "native")) throw new Error("Unknown owned SQLite snapshot command");
      if (mode !== "source") await runArtifactRustTests(cargoName, this.repoRoot, ["--lib", "sqlite_snapshot_", "--no-fail-fast"], options.snapshotSqliteTestFeatures ?? options.testFeatures);
      if (mode !== "native") {
        const { runRepositoryTestCommand } = await import("../../../🟦️.ts");
        for (const group of snapshotGroups) await runRepositoryTestCommand(process.execPath, ["test", ...group], { cwd: this.repoRoot, budgetMs: options.snapshotSqliteTestBudgetMs });
      }
    }
  }
  const packageRouter = new ScriptRouter(packageRoot).register("build", BuildScript).register("check", CheckScript).register("test", TestScript);
  if (options.snapshotSqliteTests?.length) packageRouter.register("test-snapshot-sqlite", SnapshotSqliteTestScript);
  for (const [name, Command] of Object.entries(options.commands ?? {})) packageRouter.register(name, Command);
  if (options.twins?.length) packageRouter.register("canonical-architecture", CanonicalArchitectureScript);
  const segments = process.argv.slice(2);
  await packageRouter.run(segments.length ? segments : ["test"]);
}

import { discoverCargoWorkspaces } from "../../../🗂️workspaces/🦀️cargo/🟦️.ts";
import assert from "node:assert/strict";
import { existsSync, readFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";
import { BundleScript } from "../../../../../../../🔨️modules/🏃️process/🧭️routing/🟦️.ts";
import { slash, sourceFiles } from "../../🔍️discovery/📂️source/🟦️.ts";
import { captureArtifactContract } from "../🏃️contract-capture/🟦️.ts";
import { artifactPackageInventory } from "../🧭️package-inventory/🟦️.ts";

/** 🧬️ Validates every taxonomy artifact's language-neutral package boundary. */
export class ArtifactPackageContractScript extends BundleScript {
  async run(): Promise<void> {
    const fixtureRoot = fileURLToPath(new URL("../../🧫️fixtures/artifact-packages", import.meta.url));
    const schema = JSON.parse(readFileSync(join(fixtureRoot, "🛂️schema/🔣️.json"), "utf8"));
    const fixture = JSON.parse(readFileSync(join(fixtureRoot, "🔣️.json"), "utf8"));
    const { default: Ajv2020 } = await import("ajv/dist/2020.js");
    const validate = new Ajv2020({ strict: true, allErrors: true }).compile(schema);
    for (const accepted of fixture.accepted) assert.ok(validate(accepted), JSON.stringify(validate.errors));
    for (const rejected of fixture.rejected) assert.equal(validate(rejected.value), false, `Negative fixture accepted: ${rejected.id}`);
    const contract = artifactPackageInventory(this.repoRoot);
    assert.ok(validate(contract), JSON.stringify(validate.errors));
    const cargoNames = new Set<string>(),
      nxNames = new Set<string>();
    for (const entry of contract.packages) {
      assert.ok(!cargoNames.has(entry.rust.cargoName), `Duplicate Cargo package ${entry.rust.cargoName}`);
      assert.ok(!nxNames.has(entry.rust.nxName), `Duplicate Nx project ${entry.rust.nxName}`);
      cargoNames.add(entry.rust.cargoName);
      nxNames.add(entry.rust.nxName);
      const packageRoot = join(this.repoRoot, dirname(entry.rust.manifest));
      const implementations = sourceFiles(packageRoot).filter((path) => /(?:^|\/)(?!📜️script\.ts$).+\.(?:rs|ts|tsx)$/.test(path) && !path.startsWith("dist/"));
      assert.deepEqual(implementations, [], `Rust package declarations contain implementation: ${implementations.join(", ")}`);
      const artifactMarker = "/🗿️artifacts/",
        marker = entry.root.indexOf(artifactMarker),
        parentSource = marker < 0 ? "" : `${entry.root.slice(0, marker)}/📦️packages/🦀️rust/🦀️.rs`;
      if (parentSource && existsSync(join(this.repoRoot, parentSource))) {
        const parent = readFileSync(join(this.repoRoot, parentSource), "utf8");
        assert.equal(/#\[path\s*=\s*"\.\.\/\.\.\/🗿️artifacts\//.test(parent), false, `${parentSource} recompiles taxonomy artifact implementation`);
        assert.equal(/^(?:pub\s+mod\s+(?:artifacts|editor|viewer)\b|pub\s+use\s+semio_s_artifact_)/m.test(parent), false, `${parentSource} publicly re-exports an artifact implementation`);
      }
      if (entry.typescript) {
        assert.ok(!nxNames.has(entry.typescript.nxName), `Duplicate Nx project ${entry.typescript.nxName}`);
        nxNames.add(entry.typescript.nxName);
        const declaration = JSON.parse(readFileSync(join(this.repoRoot, entry.typescript.manifest), "utf8"));
        assert.equal(declaration.type, "module");
        assert.equal(declaration.private, true);
        assert.equal(declaration.types, "./dist/🟦️.d.ts");
        assert.deepEqual(declaration.exports?.["."], entry.typescript.entry);
      }
    }
    const records = [];
    for (const scope of discoverCargoWorkspaces(this.repoRoot)) records.push(JSON.parse(await captureArtifactContract("cargo", ["metadata", "--locked", "--offline", "--format-version", "1", "--manifest-path", join(this.repoRoot, scope.manifest)], this.repoRoot, 180_000)));
    const metadata = { packages: records.flatMap(record => record.packages), resolve: { nodes: records.flatMap(record => record.resolve?.nodes ?? []) } };
    const cargoPackages = new Map<string, any>(metadata.packages.map((entry: any) => [entry.id, entry]));
    const byName = new Map<string, any>(metadata.packages.map((entry: any) => [entry.name, entry]));
    const nodes = new Map<string, any>((metadata.resolve?.nodes ?? []).map((entry: any) => [entry.id, entry]));
    for (const entry of contract.packages) {
      const cargo = byName.get(entry.rust.cargoName);
      assert.ok(cargo, `Cargo metadata omitted ${entry.rust.cargoName}`);
      assert.equal(slash(relative(this.repoRoot, cargo.manifest_path)), entry.rust.manifest);
      const visit = (id: string, requested: string[], defaults: boolean, route: string[], visited: Set<string>): void => {
        const dependency = cargoPackages.get(id);
        const enabled = new Set<string>(requested);
        if (defaults && dependency?.features?.default) enabled.add("default");
        const activated = new Set<string>();
        const forwarded = new Map<string, Set<string>>();
        const queue = [...enabled];
        while (queue.length) {
          const feature = queue.pop()!;
          for (const value of dependency?.features?.[feature] ?? []) {
            if (value.startsWith("dep:")) activated.add(value.slice(4));
            else if (value.includes("/")) {
              const [name, selected] = value.replace("?/", "/").split("/", 2);
              if (!forwarded.has(name)) forwarded.set(name, new Set());
              forwarded.get(name)!.add(selected);
            } else if (!enabled.has(value)) {
              enabled.add(value);
              queue.push(value);
            }
          }
        }
        const state = `${id}\0${[...enabled].sort().join(",")}\0${defaults}`;
        if (visited.has(state)) return;
        visited.add(state);
        const componentKind = dependency?.metadata?.semio?.["component-kind"];
        assert.ok(componentKind !== "plugin" && componentKind !== "extension", `${entry.rust.cargoName} reaches composition package ${[...route, dependency?.name].join(" -> ")}`);
        for (const edge of nodes.get(id)?.deps ?? []) {
          if (!edge.dep_kinds?.some((kind: any) => kind.kind === null)) continue;
          const target = cargoPackages.get(edge.pkg);
          const declarations = (dependency?.dependencies ?? []).filter((row: any) => row.kind === null && row.name === target?.name && (row.rename ?? row.name) === edge.name);
          const active = declarations.filter((row: any) => !row.optional || activated.has(edge.name) || enabled.has(edge.name));
          if (!active.length) continue;
          const features = new Set<string>(forwarded.get(edge.name) ?? []);
          for (const declaration of active) for (const feature of declaration.features ?? []) features.add(feature);
          visit(
            edge.pkg,
            [...features],
            active.some((row: any) => row.uses_default_features),
            [...route, dependency?.name],
            visited,
          );
        }
      };
      visit(cargo.id, [], true, [], new Set());
    }
    const legacy = sourceFiles(this.repoRoot).filter((path) => {
      if (!path.endsWith(".rs")) return false;
      try {
        return /semio_s_plugin_(?![a-z0-9_]*_test_oracle::)[a-z0-9_]+::artifacts::/.test(readFileSync(join(this.repoRoot, path), "utf8"));
      } catch (error) {
        if ((error as { code?: string }).code === "ENOENT") return false;
        throw error;
      }
    });
    assert.deepEqual(legacy, [], `Rust consumers retain composition artifact namespaces: ${legacy.join(", ")}`);
    console.log(
      `[artifact-package-contract] AJV=${fixture.accepted.length + 1}/${fixture.rejected.length} packages=${contract.packages.length} rust=${cargoNames.size} typescript=${contract.packages.filter((entry) => entry.typescript).length} dag=clean`,
    );
  }
}

import { buildBudgetMs, cmdBudgetMs, orchestratorBudgetMs, daemonBudgetMs } from "../../../../../🔨️modules/🏃️process/⏱️budget/🟦️.ts";
import { terminateOwnedProcessTree } from "../../../../../🔨️modules/🏃️process/🪓️termination/🟦️.ts";

/** 🏃️ Process execution with opt-in wall-clock budgets for repository commands and builds,
 * the `spawnSync` runners built on them, workspace-aware `.bin`
 * resolution and the dev/ship build-mode switch. Split out of `📦️packages/🟦️typescript/🟦️.ts` so a
 * consumer that only spawns a tool (the plugin package's jco/wasm-opt steps, and through them the
 * extension store and `⚙️vite.config.ts`) never drags the repository library's `🔍️discovery` taxonomy
 * walk into its module graph. */
import { spawn, spawnSync } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { prepareCargoWorkspaceInvocation } from "../🗂️workspaces/🦀️cargo/🟦️.ts";
import { getWorkspaceRoot } from "../🗂️workspaces/🟦️.ts";
import { devToolingEnv } from "./🌿️environment/🟦️.ts";

/** 🧭️Selects the opt-in build budget for Cargo and command budget for other executables; both default to unlimited. */
export function defaultBudgetMs(cmd: string): number {
  return cmd === "cargo" ? buildBudgetMs() : cmdBudgetMs();
}

/** ⏱️Timeout hint for a budget-exceeded message; `cargo` commands default to the shared target-dir lock-contention hint (by far the most common real cause), everything else to a generic budget-tuning hint. An explicit `override` always wins. */
export function budgetTimeoutHint(cmd: string, override?: string): string {
  if (override) return override;
  return cmd === "cargo"
    ? "Likely shared cargo target-dir lock contention from another concurrent session — investigate before retrying."
    : "Trim it, or raise its budget (`budgetMs`, `SEMIO_CMD_BUDGET_MS`, `SEMIO_BUILD_BUDGET_MS`).";
}

export interface RunCmdOpts {
  cwd?: string;
  env?: NodeJS.ProcessEnv;
  /** ⏱️Wall-clock budget (ms); zero disables the timeout. Defaults to [[defaultBudgetMs]]. Named wrappers use [[orchestratorBudgetOpts]] / [[daemonBudgetOpts]]. */
  budgetMs?: number;
  onTimeoutHint?: string;
  /** 🐚️ Resolve the command through the platform shell — required on native Windows for `.cmd`/`.bat` launchers such as `bunx`. */
  shell?: boolean;
}

/** ⏱️[[RunCmdOpts]] preset for nx/script orchestrators — [[orchestratorBudgetMs]] and full CPU [[devToolingEnv]]. */
export function orchestratorBudgetOpts(extra: Partial<NodeJS.ProcessEnv> = {}): RunCmdOpts {
  return { budgetMs: orchestratorBudgetMs(), env: devToolingEnv(extra) };
}

/** ⏱️[[RunCmdOpts]] preset for dev servers and long-lived daemons — [[daemonBudgetMs]] and [[devToolingEnv]]. */
export function daemonBudgetOpts(extra: Partial<NodeJS.ProcessEnv> = {}): RunCmdOpts {
  return { budgetMs: daemonBudgetMs(), env: devToolingEnv(extra) };
}

/** 🌊️ The library's cargo relay, `⚡️caching/🦀️cargo/📜️script.ts relay <cargo args…>` ([[cargoStreamingStatus]]). */
export const CARGO_RELAY_SCRIPT = join(dirname(fileURLToPath(import.meta.url)), "..", "⚡️caching", "🦀️cargo", "📜️script.ts");

/** 🌊️ Carries a relayed cargo's wall-clock budget (ms, `0` = unlimited) from [[runCmd]] into the relay. */
export const CARGO_RELAY_BUDGET_ENV = "SEMIO_CARGO_RELAY_BUDGET_MS";

/** 🌊️ Runs `cargo` with its stdout/stderr piped and forwarded, never inherited: Bun marks its own stdio `O_NONBLOCK` once
 * written and an inherited pipe shares that flag, so a cargo burst (the replayed warnings of fresh units) fails with
 * `EAGAIN` — output cut mid-line, exit 101 — as soon as a slow reader lets the 64 KiB pipe fill (ticket 26/09/23 W4: flaky
 * component builds, the trusted-catalog publish's `os-hub` build). Bun's own writer waits the pipe out. Returns cargo's exit
 * status; `budgetMs` (> 0) elapsing or a SIGINT/SIGTERM of this process ends the whole cargo tree and throws. */
export async function cargoStreamingStatus(args: readonly string[], cwd: string, env: NodeJS.ProcessEnv, budgetMs: number): Promise<number> {
  prepareCargoWorkspaceInvocation(getWorkspaceRoot(), args, cwd);
  const child = spawn("cargo", [...args], { cwd, env, stdio: ["inherit", "pipe", "pipe"], detached: process.platform !== "win32" });
  child.stdout!.pipe(process.stdout, { end: false });
  child.stderr!.pipe(process.stderr, { end: false });
  let stopped: string | undefined;
  const stop = (reason: string): void => {
    stopped ??= reason;
    if (child.exitCode === null && child.signalCode === null && child.pid) terminateOwnedProcessTree(child.pid);
  };
  const onSignal = (signal: NodeJS.Signals): void => stop(`stopped: the relay received ${signal}`);
  const budget = budgetMs > 0 ? setTimeout(() => {
    console.error(`[budget] cargo ${args.join(" ")} exceeded ${budgetMs}ms — killed. ${budgetTimeoutHint("cargo")}`);
    stop(`exceeded ${budgetMs}ms`);
  }, budgetMs) : undefined;
  process.once("SIGINT", onSignal);
  process.once("SIGTERM", onSignal);
  try {
    const [code, signal] = await new Promise<[number | null, NodeJS.Signals | null]>((accept, reject) => {
      child.once("error", reject);
      child.once("close", (exitCode, exitSignal) => accept([exitCode, exitSignal]));
    });
    if (stopped || signal) throw new Error(`cargo ${args.join(" ")} ${stopped ?? `killed by signal ${signal}`}`);
    return code ?? 1;
  } finally {
    if (budget) clearTimeout(budget);
    process.removeListener("SIGINT", onSignal);
    process.removeListener("SIGTERM", onSignal);
  }
}

/** ⏱️Shared `spawnSync` core for [[runCmd]]/[[runCmdStatus]]: throws on spawn error, budget timeout, or signal kill (printing `[budget]` first on timeout); otherwise returns the exit status. `cargo` runs through
 * [[CARGO_RELAY_SCRIPT]] (POSIX), so it never writes to an inherited, possibly non-blocking descriptor ([[cargoStreamingStatus]]). */
function runCmdInternal(cmd: string, args: string[], opts: RunCmdOpts): number {
  if (cmd === "cargo") prepareCargoWorkspaceInvocation(getWorkspaceRoot(), args, opts.cwd ?? process.cwd());
  const budgetMs = opts.budgetMs ?? defaultBudgetMs(cmd);
  const formattedArgs = [...args];
  if (cmd === "bun" || cmd === process.execPath) {
    if (formattedArgs[0] && !formattedArgs[0].startsWith("-") && !formattedArgs[0].includes("/") && !formattedArgs[0].includes("\\") && !workspaceScriptExists(formattedArgs[0])) {
      const resolved = resolveWorkspaceBin(formattedArgs[0], opts.cwd ?? process.cwd());
      if (resolved) {
        formattedArgs[0] = resolved;
      }
    }
  }
  const relayed = cmd === "cargo" && process.platform !== "win32";
  const result = relayed
    ? spawnSync(process.versions.bun ? process.execPath : "bun", [CARGO_RELAY_SCRIPT, "relay", ...formattedArgs], {
        stdio: "inherit",
        cwd: opts.cwd,
        env: { ...(opts.env ?? process.env), [CARGO_RELAY_BUDGET_ENV]: String(budgetMs) },
        timeout: budgetMs > 0 ? budgetMs + 60_000 : 0,
        killSignal: "SIGTERM",
        shell: false,
      })
    : spawnSync(cmd, formattedArgs, {
        stdio: "inherit",
        cwd: opts.cwd,
        env: opts.env ?? process.env,
        timeout: budgetMs,
        killSignal: "SIGKILL",
        shell: opts.shell ?? false,
      });
  if (result.error) {
    if ((result.error as NodeJS.ErrnoException).code === "ETIMEDOUT") {
      console.error(`[budget] ${cmd} ${args.join(" ")} exceeded ${budgetMs}ms — killed. ${budgetTimeoutHint(cmd, opts.onTimeoutHint)}`);
    }
    throw result.error;
  }
  if (result.signal) throw new Error(`${cmd} ${args.join(" ")} killed by signal ${result.signal}`);
  return result.status ?? 1;
}

/**
 * 🏃️Runs a subprocess with inherited stdio and an opt-in wall-clock budget (default [[defaultBudgetMs]]);
 * throws on non-zero exit, signal, or budget exceed (the `[budget]` line is printed
 * to stderr first so it survives a caller's try/catch, e.g. [[tryRun]]).
 */
export function runCmd(cmd: string, args: string[], opts: RunCmdOpts = {}): void {
  const status = runCmdInternal(cmd, args, opts);
  if (status !== 0) throw new Error(`${cmd} ${args.join(" ")} exited with status ${status}`);
}

/** 🏃️Like [[runCmd]] but returns the exit status instead of throwing on non-zero exit — for call sites
 *  that branch on it. Budget exceed still prints `[budget]` and throws (never silently returns a status). */
export function runCmdStatus(cmd: string, args: string[], opts: RunCmdOpts = {}): number {
  return runCmdInternal(cmd, args, opts);
}

/** 🏃️Like [[runCmd]] but ignores failures, including timeouts from an explicitly configured budget. */
export function tryRun(cmd: string, args: string[], opts: RunCmdOpts = {}): void {
  try {
    runCmd(cmd, args, opts);
  } catch {
    /* optional */
  }
}

/** 🔍️ Resolves a CLI executable in `cwd` or workspace root's `node_modules/.bin` to avoid `bun x` cwd resolution bugs on emoji/ZWJ paths. */
export function resolveWorkspaceBin(binName: string, cwd: string = process.cwd()): string | null {
  const shortName = binName.includes("/") ? binName.split("/").pop()! : binName;
  const localBin = join(cwd, "node_modules", ".bin", shortName);
  if (existsSync(localBin)) return localBin;
  const rootBin = join(getWorkspaceRoot(), "node_modules", ".bin", shortName);
  if (existsSync(rootBin)) return rootBin;
  return null;
}

let workspaceScriptNames: ReadonlySet<string> | null = null;

/** 📜️Whether the workspace `package.json` declares a script under `name`. A declared script is the
 * workspace's deliberate wrapper for that tool (`nx` routes through the caching bootstrap, which
 * owns the daemon-served project graph the async ES-module inference plugin needs), so `bun <name>`
 * must reach the script and never the bare `node_modules/.bin` entry of the same name. */
export function workspaceScriptExists(name: string): boolean {
  if (workspaceScriptNames === null) {
    const manifest = join(getWorkspaceRoot(), "package.json");
    const scripts = existsSync(manifest) ? (JSON.parse(readFileSync(manifest, "utf8")) as { scripts?: Record<string, string> }).scripts ?? {} : {};
    workspaceScriptNames = new Set(Object.keys(scripts));
  }
  return workspaceScriptNames.has(name);
}

/** 🟢️Runs a CLI tool using `node` synchronously in `cwd`, returning status code. */
export function runNodeBinStatus(args: string[], cwd: string = process.cwd(), env: NodeJS.ProcessEnv = process.env): number {
  const binName = args[0]!;
  const resolved = resolveWorkspaceBin(binName, cwd);
  const executable = resolved ?? binName;
  const result = spawnSync("node", [executable, ...args.slice(1)], { cwd, env, shell: false, stdio: "inherit" });
  if (result.error) {
    console.error(result.error);
    return 1;
  }
  return result.status ?? 1;
}

/** 🟢️Runs a CLI tool using `node` synchronously in `cwd`. */
export function runNodeBin(args: string[], cwd: string = process.cwd(), env: NodeJS.ProcessEnv = process.env): void {
  const status = runNodeBinStatus(args, cwd, env);
  if (status !== 0) process.exit(status);
}

/** 🚦️ Whether child builds should use fast dev artifacts or ship optimization. */
export type SemioBuildMode = "dev" | "ship";

/** 🚦️ `ship` only when `SEMIO_BUILD_MODE=ship`; default is dev for local/agent loops. */
export function semioBuildMode(): SemioBuildMode {
  return process.env.SEMIO_BUILD_MODE === "ship" ? "ship" : "dev";
}

/** 🚀️ Env for nx/build orchestrators so spawned crate `wasm` scripts inherit ship mode. */
export function semioShipEnv(): NodeJS.ProcessEnv {
  return { ...process.env, SEMIO_BUILD_MODE: "ship" };
}

/** 📂 Cargo output directory name for a profile (`dev` → `debug`). */
export function cargoProfileDir(profile: string): string {
  return profile === "dev" ? "debug" : profile;
}

