    if (typeof selected.sha256 !== "string" || !/^[0-9a-f]{64}$/u.test(selected.sha256) || selected.mode !== "0644" || !Number.isSafeInteger(selected.size) || (selected.size as number) < 0) return fail(label + " tuple");
